{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.capsule_inventory_projection AS WITH focus_capsules AS ( SELECT DISTINCT UPPER(TRIM(SKU)) AS SKU_GROUP, TRIM(COLLECTION) AS CAPSULE FROM snitch_db.maplemonk.collection_sku_mapped_sheet1 WHERE SKU IS NOT NULL AND COLLECTION IS NOT NULL AND LOWER(TRIM(COLLECTION)) IN ( \'embroided shirts\', \'botanical theme\', \'street fc\', \'street fc plus\', \'golf polo theme\', \'photo print\', \'try less denim\', \'printed shirts\' ) ), capsule_launch AS ( SELECT UPPER(TRIM(CAPSULE)) AS CAPSULE, MIN(LAUNCH_DATE) AS LAUNCH_DATE FROM snitch_db.maplemonk.rolling_30_days_dashboard WHERE CAPSULE IS NOT NULL AND LAUNCH_DATE IS NOT NULL GROUP BY UPPER(TRIM(CAPSULE)) ), last_60_days_sales AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS SKU_GROUP, SUM( COALESCE(TOTAL_QTY, 0) ) AS LAST_60D_QTY FROM snitch_db.maplemonk.daily_sales_summary_dashboard WHERE DATE >= DATEADD(DAY, -60, CURRENT_DATE()) AND DATE < CURRENT_DATE() GROUP BY UPPER(TRIM(SKU_GROUP)) ), sales_since_launch AS ( SELECT UPPER(TRIM(h.SKU_GROUP)) AS SKU_GROUP, SUM( COALESCE(h.TOTAL_QTY, 0) ) AS TOTAL_QTY_SINCE_LAUNCH FROM snitch_db.maplemonk.daily_sales_summary_dashboard h INNER JOIN focus_capsules fc ON UPPER(TRIM(h.SKU_GROUP)) = fc.SKU_GROUP INNER JOIN capsule_launch cl ON UPPER(TRIM(fc.CAPSULE)) = cl.CAPSULE WHERE h.DATE >= cl.LAUNCH_DATE AND h.DATE < CURRENT_DATE() GROUP BY UPPER(TRIM(h.SKU_GROUP)) ), capsule_sales AS ( SELECT fc.CAPSULE, cl.LAUNCH_DATE, DATEDIFF( DAY, cl.LAUNCH_DATE, CURRENT_DATE() ) + 1 AS DAYS_SINCE_LAUNCH, SUM( COALESCE( l60.LAST_60D_QTY, 0 ) ) AS CAPSULE_LAST_60D_QTY, SUM( COALESCE( ssl.TOTAL_QTY_SINCE_LAUNCH, 0 ) ) AS CAPSULE_QTY_SINCE_LAUNCH FROM focus_capsules fc LEFT JOIN capsule_launch cl ON UPPER(TRIM(fc.CAPSULE)) = cl.CAPSULE LEFT JOIN last_60_days_sales l60 ON fc.SKU_GROUP = l60.SKU_GROUP LEFT JOIN sales_since_launch ssl ON fc.SKU_GROUP = ssl.SKU_GROUP GROUP BY fc.CAPSULE, cl.LAUNCH_DATE ), capsule_run_rate AS ( SELECT CAPSULE, LAUNCH_DATE, DAYS_SINCE_LAUNCH, CAPSULE_LAST_60D_QTY, CAPSULE_QTY_SINCE_LAUNCH, CASE WHEN DAYS_SINCE_LAUNCH IS NULL THEN NULL WHEN DAYS_SINCE_LAUNCH >= 60 THEN ROUND( CAPSULE_LAST_60D_QTY / 60.0, 2 ) WHEN DAYS_SINCE_LAUNCH > 0 THEN ROUND( CAPSULE_QTY_SINCE_LAUNCH / DAYS_SINCE_LAUNCH, 2 ) ELSE NULL END AS CAPSULE_DAILY_RUN_RATE FROM capsule_sales ), capsule_inventory AS ( SELECT UPPER(TRIM(CAPSULE)) AS CAPSULE, SUM( COALESCE( TOTAL_INVENTORY, 0 ) ) AS CURRENT_INVENTORY FROM snitch_db.maplemonk.capsule_master_summary_tbl WHERE CAPSULE IS NOT NULL GROUP BY UPPER(TRIM(CAPSULE)) ), final_metrics AS ( SELECT crr.CAPSULE, crr.LAUNCH_DATE, crr.DAYS_SINCE_LAUNCH, crr.CAPSULE_LAST_60D_QTY, crr.CAPSULE_QTY_SINCE_LAUNCH, crr.CAPSULE_DAILY_RUN_RATE, COALESCE( ci.CURRENT_INVENTORY, 0 ) AS CURRENT_INVENTORY, ROUND( COALESCE( ci.CURRENT_INVENTORY, 0 ) / NULLIF( crr.CAPSULE_DAILY_RUN_RATE, 0 ), 0 ) AS PROJECTED_DAYS_TO_EXHAUST FROM capsule_run_rate crr LEFT JOIN capsule_inventory ci ON UPPER(TRIM(crr.CAPSULE)) = ci.CAPSULE ) SELECT CAPSULE, LAUNCH_DATE, DAYS_SINCE_LAUNCH, CAPSULE_LAST_60D_QTY, CAPSULE_QTY_SINCE_LAUNCH, CAPSULE_DAILY_RUN_RATE, CURRENT_INVENTORY, PROJECTED_DAYS_TO_EXHAUST, CASE WHEN DAYS_SINCE_LAUNCH < 60 THEN \'SALES SINCE LAUNCH\' ELSE \'LAST 60 DAYS\' END AS RUN_RATE_BASIS, CASE WHEN CURRENT_INVENTORY = 0 THEN \'OUT OF STOCK\' WHEN CAPSULE_DAILY_RUN_RATE IS NULL THEN \'NO SALES DATA\' WHEN CAPSULE_DAILY_RUN_RATE = 0 THEN \'NO SALES RUN RATE\' WHEN PROJECTED_DAYS_TO_EXHAUST <= 15 THEN \'CRITICAL\' WHEN PROJECTED_DAYS_TO_EXHAUST <= 30 THEN \'LOW INVENTORY\' WHEN PROJECTED_DAYS_TO_EXHAUST <= 60 THEN \'MODERATE\' ELSE \'HEALTHY\' END AS INVENTORY_STATUS FROM final_metrics ORDER BY PROJECTED_DAYS_TO_EXHAUST ASC NULLS LAST;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            